		return "", fmt.Errorf("bodyFile contains absolute path (%s). only relative is supported", filePath)
	}

	resolvedPath, err := util.ResolveAndValidatePath(hf.Cfg.ResponsesBodyFilesPath, filePath)
	if err != nil {
